class ParkingSystem:
    def __init__(self, big: int, medium: int, small: int):
        self.free = [big, medium, small]         # remaining slots per car type

    def addCar(self, carType: int) -> bool:
        if self.free[carType - 1] > 0:
            self.free[carType - 1] -= 1
            return True
        return False
